css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.1;letter-spacing:-.025em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;position:relative;z-index:1}
section{padding:96px 0;position:relative}
.dk{background:var(--k);color:#fff}.lt{background:var(--w);color:var(--ink)}.gr{background:var(--g);color:var(--ink)}
.dk p{color:var(--dmute)}.lt p,.gr p{color:var(--mute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.btn.xl{padding:18px 32px;font-size:17px}
.b-l{background:var(--l);color:var(--k)}.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.eb{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;margin-bottom:22px}
.eb::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.dk .eb{color:var(--l)}.lt .eb,.gr .eb{color:var(--ink)}.lt .eb::before,.gr .eb::before{background:var(--k)}
.h2{font-size:clamp(30px,4.6vw,58px);letter-spacing:-.035em;line-height:1.05}
.sh{margin-bottom:52px}.sh p{margin-top:18px;font-size:17px;max-width:620px}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}nav .btn{padding:10px 18px;font-size:14px}
/* motion */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
.mk{display:block;overflow:hidden;padding-bottom:.1em;margin-bottom:-.1em}
.mk>span{display:block}
.js .mk>span{transform:translateY(110%);transition:transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.js .in .mk>span,.js .mk.in>span{transform:none}
/* hero */
.hero{padding:80px 0 88px;background:radial-gradient(circle at 90% 0,#C7FF3F12,transparent 45%),var(--k)}
.hero .wrap{display:grid;grid-template-columns:1.05fr 1fr;gap:48px;align-items:center}
.hero h1{font-size:clamp(34px,4.7vw,66px);line-height:1.02;letter-spacing:-.04em}
.hero h1 em{font-style:normal;color:var(--l);background:linear-gradient(var(--l),var(--l)) 0 100%/100% 3px no-repeat;padding-bottom:.06em}
.hero .sub{margin:24px 0 18px;font-size:clamp(17px,2vw,19px);max-width:520px;color:#d6d6da}
.hero .sec{font:500 15px Inter;color:#fff;border-left:2px solid var(--l);padding-left:14px;margin-bottom:32px;line-height:1.5}
.hero .sec span{color:var(--dmute);display:block}
.stage{position:relative;height:540px}
.sc{position:absolute;background:var(--k2);border:1px solid var(--dline);border-radius:18px;padding:18px;box-shadow:0 20px 40px #0008}
.sc>.t{display:inline-block;font:600 11px Inter;letter-spacing:.08em;color:var(--k);background:var(--l);padding:4px 10px;border-radius:99px;margin-bottom:14px}
.s1{left:0;top:318px;width:330px}.s2{left:150px;top:160px;width:330px}.s3{right:0;top:0;width:260px}
.stage svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.ln{height:7px;border-radius:4px;background:#2a2a2e;margin-bottom:8px}.ln.w{height:12px;width:65%;background:#ececec}.ln.s{width:55%}
.pill{display:inline-block;padding:6px 13px;border-radius:99px;background:var(--l);color:var(--k);font:600 11px Inter}
.ph{position:absolute;right:16px;top:-26px;width:72px;border:2px solid #34343a;border-radius:16px;background:#17171a;padding:12px 8px;box-shadow:0 14px 30px #000a}
.nr{display:flex;align-items:center;gap:8px;font-size:11.5px;color:#d8d8dc}
.nr span{padding:7px 10px;border-radius:9px;background:#1b1b1f;border:1px solid var(--dline)}.nr span.a{border-color:var(--l);color:var(--l)}.nr s{flex:1;height:2px;background:var(--l);opacity:.5;text-decoration:none}
.nd-lit{animation:lit 1.4s ease-out;animation-delay:calc(var(--i)*.45s + .9s)}
@keyframes lit{0%,100%{box-shadow:none}35%{box-shadow:0 0 0 4px #C7FF3F33}}
.bars{display:flex;align-items:flex-end;gap:7px;height:96px}.bars i{flex:1;background:#2a2a2e;border-radius:4px 4px 0 0}.bars i:last-child{background:var(--l)}
.cap{margin-top:12px;font-size:13px;color:var(--dmute)}
/* POV */
.pv{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-bottom:64px;align-items:end}
.pv .h2 span{display:block}.pv .h2 .m{color:#9a9c98}
.pv .intro{font-size:17px;max-width:480px;margin-bottom:18px}
.pl{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0 24px}
.pl li{padding:11px 0;border-top:1px solid var(--line);font-size:15px;display:flex;gap:10px;color:var(--ink)}.pl li::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--k);margin-top:10px;flex:none}
.br{display:grid;grid-template-columns:repeat(5,1fr);gap:0;align-items:end}
.bn{position:relative;margin-right:28px;background:var(--k);color:#fff;border-radius:18px;padding:20px 18px;display:flex;flex-direction:column;justify-content:flex-end;transition:transform .25s}
.bn:hover{transform:translateY(-4px)}
.bn:nth-child(1){min-height:130px}.bn:nth-child(2){min-height:178px}.bn:nth-child(3){min-height:226px}.bn:nth-child(4){min-height:274px}.bn:nth-child(5){min-height:322px;background:var(--l);color:var(--k);margin-right:0}
.bn small{font:600 11px Inter;letter-spacing:.08em;color:var(--l);margin-bottom:8px}.bn:nth-child(5) small{color:var(--k)}
.bn b{font:600 17px Sora;line-height:1.2}
.bn::after{content:"→";position:absolute;left:100%;bottom:22px;width:28px;text-align:center;color:var(--k);font:600 16px Sora}.bn:last-child::after{display:none}
/* model */
.mi{padding:96px 0 40px}
.mi h2{font-size:clamp(44px,9vw,120px);letter-spacing:-.05em;line-height:.95}.mi h2 .mk:nth-child(2) span{color:var(--l)}
.mb .wrap{display:grid;grid-template-columns:1fr 1.2fr;gap:56px;align-items:center}
.mb.rev .tx{order:2}
.num{font:700 clamp(60px,8vw,104px)/1 Sora;letter-spacing:-.05em;-webkit-text-stroke:1.5px currentColor;color:transparent;margin-bottom:6px;opacity:.5}
.mb .tag{font:600 13px Inter;letter-spacing:.1em;margin-bottom:14px}.dk .tag{color:var(--l)}.lt .tag,.gr .tag{color:var(--ink)}
.mb h3{font-size:clamp(26px,3.2vw,42px);letter-spacing:-.03em;margin-bottom:16px}
.mb .tx>p{font-size:17px;margin-bottom:24px;max-width:460px}
.cp{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.cp li{font-size:13px;font-weight:500;padding:6px 13px;border-radius:99px}
.gr .cp li,.lt .cp li{background:#fff;border:1px solid var(--line)}.dk .cp li{background:var(--k2);border:1px solid var(--dline);color:#e0e0e4}
.pn{border-radius:28px;padding:32px;min-height:380px;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}
.gr .pn{background:var(--k)}.dk .pn{background:var(--k2);border:1px solid var(--dline)}.lt .pn{background:#fff;border:1px solid var(--line)}
.brw{width:100%;background:var(--k2);border:1px solid var(--dline);border-radius:16px;overflow:hidden;position:relative}
.top{display:flex;gap:6px;padding:11px 14px;border-bottom:1px solid var(--dline)}.top b{width:9px;height:9px;border-radius:50%;background:#333}
.bd{padding:18px}.bd .hb{border-radius:12px;background:var(--k);border:1px solid var(--dline);padding:22px;margin-bottom:12px}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.g3 div{height:54px;border-radius:9px;background:#17171a;border:1px solid var(--dline)}
.php{position:absolute;right:26px;bottom:-34px;width:110px;border:2px solid #34343a;border-radius:22px;background:#17171a;padding:14px 10px 40px;box-shadow:0 14px 30px #000a}
.wf{display:grid;grid-template-columns:auto 1fr auto 1fr auto;gap:10px;align-items:center;width:100%}
.wf .b{background:var(--k);border:1px solid var(--dline);border-radius:12px;padding:12px 14px;font-size:13px;font-weight:500;color:#fff;text-align:center}.wf .b.a{border-color:var(--l);box-shadow:0 0 0 4px #C7FF3F1a}
.wf .c{display:flex;flex-direction:column;gap:8px}
.wf .ar{height:2px;background:linear-gradient(90deg,var(--l),#2a2a2e)}
.gb{display:flex;align-items:flex-end;gap:14px;height:230px;width:100%;padding:0 6px;border-bottom:2px solid var(--line)}
.gb i{flex:1;border-radius:8px 8px 0 0;background:#fff;border:1.5px solid var(--k);border-bottom:0}.gb i:last-child{background:var(--l)}
.gl{display:flex;justify-content:space-between;width:100%;margin-top:12px;font:600 12px Inter;color:var(--mute);position:absolute;left:0;right:0;bottom:12px;padding:0 38px}
/* different */
.dc{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.d{background:var(--k2);border:1px solid var(--dline);border-radius:22px;padding:28px;transition:transform .25s,border-color .25s;min-height:300px;display:flex;flex-direction:column}
.d:hover{transform:translateY(-6px);border-color:#3a3a40}
.d .n{font:600 13px Sora;color:var(--l);margin-bottom:auto;padding-bottom:44px}.d h3{font-size:19px;margin-bottom:10px}.d p{font-size:15px}
/* who */
.ic{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.i{background:#fff;border:1px solid var(--line);border-radius:20px;padding:22px;display:flex;flex-direction:column;transition:transform .25s,border-color .25s}
.i:hover{transform:translateY(-5px);border-color:var(--k)}
.i .sq{width:44px;height:44px;border-radius:12px;background:var(--k);display:grid;place-items:center;margin-bottom:18px}
.i svg{width:22px;height:22px;stroke:var(--l);fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.i h3{font-size:16.5px;margin-bottom:8px}.i p{font-size:14px;margin-bottom:16px}
.i a{margin-top:auto;font-weight:600;font-size:14px;color:var(--ink);border-bottom:2px solid var(--l);align-self:flex-start;padding-bottom:1px}
/* process */
.ps{display:grid;grid-template-columns:repeat(5,1fr);gap:0}
.st{position:relative;padding-right:22px}
.st .dot{width:42px;height:42px;border-radius:50%;background:var(--k2);border:2px solid var(--dline);display:grid;place-items:center;font:600 13px Sora;color:var(--l);margin-bottom:20px;position:relative;z-index:1}
.st::after{content:"";position:absolute;left:52px;right:8px;top:20px;height:2px;background:var(--l);transform-origin:left;transform:scaleX(1);opacity:.6}
.js .st::after{transform:scaleX(0);transition:transform .9s ease;transition-delay:calc(var(--d,0s) + .3s)}.js .st.in::after{transform:scaleX(1)}
.st:last-child::after{display:none}
.st h3{font-size:18px;letter-spacing:.04em;margin-bottom:12px}.st ul{list-style:none;margin:0;padding:0}.st li{padding:7px 0;border-top:1px solid var(--dline);color:#d0d0d4;font-size:14.5px}
/* principles */
.pr .row{margin-bottom:6px}
.pr .row:nth-child(even){margin-left:clamp(0px,10vw,150px)}
.pr .p{font:700 clamp(30px,6.4vw,88px)/1.04 Sora;letter-spacing:-.045em;display:inline-block;transition:transform .35s}
.pr .p:hover{transform:translateX(10px)}
.pr .p b{font-weight:700;color:var(--ink)}.pr .p span{color:#b5b7b2}
/* team */
.tm{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.t{border:1.5px dashed #3a3a40;border-radius:20px;padding:16px;transition:transform .25s}.t:hover{transform:translateY(-4px)}
.t .av{aspect-ratio:1;border-radius:14px;background:var(--k2);display:grid;place-items:center;font-size:12px;color:#6f6f75;margin-bottom:14px}
.t h3{font-size:15.5px;margin-bottom:6px}.t p{font-size:13px;color:#6f6f75}
.fine{margin-top:22px;font-size:14px}
/* tech */
.tg{display:grid;grid-template-columns:repeat(5,1fr);gap:24px;border-top:1px solid var(--line);padding-top:32px}
.tg h4{font:600 12px Inter;letter-spacing:.1em;color:var(--mute);margin-bottom:16px}
.tg span{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);font:600 16px Sora;color:var(--ink)}.tg span::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--k);opacity:.85}
/* cta */
.cta{background:var(--l);color:var(--k);padding:112px 0}
.cta .eb{color:var(--k)}.cta .eb::before{background:var(--k)}
.cta h2{font-size:clamp(36px,6.4vw,84px);letter-spacing:-.045em;line-height:1;max-width:900px}
.cta p{margin:24px 0 36px;font-size:19px;max-width:520px;color:#2a3300}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.fg{display:grid;grid-template-columns:1.6fr repeat(4,1fr);gap:36px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* 1280 */
@media(max-width:1280px){.ic{grid-template-columns:repeat(4,1fr)}.tm{grid-template-columns:repeat(3,1fr)}}
/* 1024 */
@media(max-width:1020px){
.hero .wrap,.pv,.mb .wrap{grid-template-columns:1fr}.mb.rev .tx{order:0}.stage{max-width:560px;width:100%;margin:0 auto}
.dc{grid-template-columns:1fr 1fr}.ic{grid-template-columns:repeat(3,1fr)}.tg{grid-template-columns:repeat(3,1fr)}
.br{grid-template-columns:1fr}.bn{margin:0 0 28px;min-height:0!important}.bn::after{content:"↓";left:50%;top:100%;bottom:auto;transform:translateX(-50%);height:28px;line-height:28px}
.ps{grid-template-columns:1fr;gap:0}.st{display:grid;grid-template-columns:42px 1fr;column-gap:20px;padding:0 0 32px}.st .dot{grid-row:span 2;margin:0}.st::after{left:20px;right:auto;top:42px;bottom:-4px;width:2px;height:auto;transform-origin:top}
.js .st::after{transform:scaleY(0)}.js .st.in::after{transform:scaleY(1)}.st:last-child{padding-bottom:0}
.fg{grid-template-columns:1fr 1fr 1fr}}
/* 768 */
@media(max-width:860px){nav ul{display:none}.ic,.tg{grid-template-columns:repeat(2,1fr)}.tm{grid-template-columns:repeat(2,1fr)}}
/* 390 / 360 */
@media(max-width:600px){
section{padding:68px 0}.wrap{padding:0 20px}.hero{padding:56px 0 60px}.mi{padding:68px 0 24px}
.stage{height:auto;display:flex;flex-direction:column;gap:14px}.sc{position:static;width:auto}.s2{margin-left:14px}.s3{margin-left:28px}.stage svg{display:none}.ph{top:12px}
.pl,.dc,.ic,.tg,.tm{grid-template-columns:1fr}.pl{gap:0}.d{min-height:0}.d .n{padding-bottom:24px}
.pn{padding:18px;min-height:0}.php{display:none}.wf{grid-template-columns:1fr}.wf .ar{width:2px;height:22px;margin:0 auto;background:var(--l)}
.gb{height:170px}.gl{padding:0 20px;font-size:11px}.pr .row:nth-child(even){margin-left:0}.pr .p:hover{transform:none}
.ctas .btn{width:100%;justify-content:center}.fg{grid-template-columns:1fr 1fr}.fg>div:first-child{grid-column:span 2}.cta{padding:76px 0}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv,.js .mk>span{opacity:1;transform:none}.js .st::after{transform:none}}

js:
(function(){
  var els=document.querySelectorAll('.rv');
  if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    els.forEach(function(e){e.classList.add('in')});return;
  }
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});
  },{threshold:.12,rootMargin:'0px 0px -6% 0px'});
  els.forEach(function(e){io.observe(e)});
})();
